import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Category","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/category/index.md","filePath":"api/graphql-api/shop/category/index.md"}'),i={name:"api/graphql-api/shop/category/index.md"};function s(n,e,l,h,d,p){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to &quot;Category&quot;">​</a></h1><p>The Category menu exposes the storefront&#39;s category structure — both as a flat list and as a nested tree — so a client can build navigation menus, category landing pages, and breadcrumb trails.</p><h2 id="flat-list-vs-tree" tabindex="-1">Flat list vs. tree <a class="header-anchor" href="#flat-list-vs-tree" aria-label="Permalink to &quot;Flat list vs. tree&quot;">​</a></h2><ul><li>The <strong>tree</strong> query returns categories nested under their parents, which is what you want for a navigation menu or a category sidebar.</li><li>The <strong>categories</strong> query returns a flat, paginated list — useful when you just need to page through every category.</li><li>The <strong>single category</strong> query returns one category&#39;s full details by id.</li></ul><p>Only active, storefront-visible categories are returned.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/tree-categories.html">Tree Categories</a></td><td><code>categoryTree</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/categories.html">Categories</a></td><td><code>categories</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-category.html">Single Category</a></td><td><code>category(id:)</code> query</td></tr></tbody></table><p>These are public read endpoints — they require the storefront key header but no customer Bearer token. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',8)]))}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
